// api/engine/index.mjs — engine selection. One place decides, so no route ever guesses.

import { makeMockEngine } from "./mock.mjs";
import { makeForgeEngine } from "./forge.mjs";

/**
 * "none" is a real engine and it is the default now: since the plan drawing, the layout diagram and the
 * plant overlay are all generated by us from the crop table, a visit no longer needs the GPU at all. The
 * per-photo illustration was retired — it was pretty, it could not be trusted with information, and it
 * was the only reason a visit cost GPU seconds. Set RENDER_ILLUSTRATION=yes to bring it back.
 */
export function makeEngine(name = process.env.ENGINE || "mock", opts = {}) {
  if (name === "forge") return makeForgeEngine(opts);
  if (name === "none") {
    return {
      name: "none",
      denoise: 0,
      async available() { return true; },
      async busy() { return false; },
      async plan() { return { engine: "none", mime: "image/png", imageB64: null }; }
    };
  }
  return makeMockEngine();
}
